-- Compact the artifact storage-accounting triggers from
-- 20261030224950_artifact_aggregate_storage_budget (#4647, #4764).
--
-- Every per-table trigger there repeated the same five statements with long
-- size expressions inline. SQLite parses the whole schema on every new
-- connection, so those ~110 KB of trigger text made each connection (and
-- therefore every test fixture) measurably slower. The accounting rules now
-- live once in artifact_storage_charge_apply; each table trigger computes its
-- workspace and size once and hands them over. Behaviour is unchanged:
--   op 'i': ensure the workspace row, add new_bytes (unclamped), global +=;
--   op 'd': subtract old_bytes clamped at 0 from workspace and global;
--   op 'u': same workspace -> clamped delta; moved workspace -> clamped
--           decrement on the old one, ensure + unclamped increment on the
--           new one; global gets the clamped delta.
-- The capacity triggers on the counter tables still raise
-- artifact_storage_quota and abort the caller's statement as before.
CREATE VIEW artifact_storage_charge(op,old_ws,new_ws,old_bytes,new_bytes) AS SELECT NULL,NULL,NULL,0,0 WHERE 0;
CREATE TRIGGER artifact_storage_charge_apply INSTEAD OF INSERT ON artifact_storage_charge
BEGIN
 INSERT INTO artifact_storage_workspaces(workspace_id,max_bytes) SELECT NEW.new_ws,workspace_max_bytes FROM artifact_storage_global WHERE id=1 AND NEW.op<>'d' AND NEW.new_ws IS NOT NULL ON CONFLICT(workspace_id) DO NOTHING;
 UPDATE artifact_storage_workspaces SET used_bytes=used_bytes+NEW.new_bytes WHERE NEW.op='i' AND workspace_id=NEW.new_ws;
 UPDATE artifact_storage_workspaces SET used_bytes=max(0,used_bytes-NEW.old_bytes) WHERE NEW.op='d' AND workspace_id=NEW.old_ws;
 UPDATE artifact_storage_workspaces SET used_bytes=max(0,used_bytes+NEW.new_bytes-NEW.old_bytes) WHERE NEW.op='u' AND workspace_id=NEW.new_ws AND NEW.new_ws=NEW.old_ws;
 UPDATE artifact_storage_workspaces SET used_bytes=max(0,used_bytes-NEW.old_bytes) WHERE NEW.op='u' AND workspace_id=NEW.old_ws AND NEW.new_ws<>NEW.old_ws;
 UPDATE artifact_storage_workspaces SET used_bytes=used_bytes+NEW.new_bytes WHERE NEW.op='u' AND workspace_id=NEW.new_ws AND NEW.new_ws<>NEW.old_ws;
 UPDATE artifact_storage_global SET used_bytes=CASE NEW.op WHEN 'i' THEN used_bytes+NEW.new_bytes ELSE max(0,used_bytes+NEW.new_bytes-NEW.old_bytes) END WHERE id=1;
END;
DROP TRIGGER artifact_version_blobs_storage_insert;
CREATE TRIGGER artifact_version_blobs_storage_insert AFTER INSERT ON artifact_version_blobs BEGIN INSERT INTO artifact_storage_charge VALUES('i',NULL,NEW.workspace_id,0,coalesce(length(CAST(NEW.content AS BLOB)),0)+128); END;
